/**
 * Private paging helpers shared by the repositories in this directory.
 *
 * Not part of the public data-access surface — repositories re-export nothing
 * from here. Keyset (cursor) pagination is expressed as a range on the sort
 * column, which lets SQLite serve every page from the `(org_id, <sort>)` index.
 */
import { lt } from "drizzle-orm";
import { decodeCursor, encodeCursor } from "./base-repository";
import { makePage } from "@/types/common";
import type { Page } from "@/types/common";
import type { SQL } from "drizzle-orm";
import type { SQLiteColumn } from "drizzle-orm/sqlite-core";

export interface KeysetSort {
  readonly sortColumn: SQLiteColumn;
  readonly idColumn: SQLiteColumn;
}

/**
 * Predicate that resumes a descending listing after `cursor`. Returns
 * `undefined` for a first page or an unparseable cursor — a bad cursor
 * degrades to "start from the top", never to an error page.
 */
export function keysetPredicate(
  sort: KeysetSort,
  cursor: string | null | undefined,
): SQL | undefined {
  if (!cursor) return undefined;
  const decoded = decodeCursor(cursor);
  if (!decoded) return undefined;

  // Listings are newest first, so the next page is everything older than the
  // last row the caller was shown.
  return lt(sort.sortColumn, decoded.sortValue);
}

/** SQLite tolerates a `LIMIT` of `n + 1`; that extra row is the has-more probe. */
export function probeLimit(limit: number): number {
  return Math.max(1, Math.min(limit, 100)) + 1;
}

/**
 * Turns an over-fetched row array into a `Page`, dropping the probe row and
 * deriving the next cursor from the last row that survived.
 */
export function toPage<TRow, TOut>(
  rows: readonly TRow[],
  limit: number,
  total: number,
  map: (row: TRow) => TOut,
  cursorOf: (row: TRow) => { id: string; sortValue: string },
): Page<TOut> {
  const capped = Math.max(1, Math.min(limit, 100));
  const hasMore = rows.length > capped;
  const visible = hasMore ? rows.slice(0, capped) : rows;
  const last = visible.at(-1);

  const nextCursor =
    hasMore && last
      ? encodeCursor(cursorOf(last).id, cursorOf(last).sortValue)
      : null;

  return makePage(visible.map(map), nextCursor, total);
}

/** Drops the `undefined` slots so `and(...)` never sees a hole. */
export function compact(
  ...predicates: readonly (SQL | undefined)[]
): readonly SQL[] {
  return predicates.filter((value): value is SQL => value !== undefined);
}
/**
 * Turns a repository `Page` into what the pagination UI needs. Repositories
 * return cursor pages; the UI wants page counts and a "there is more" cursor,
 * and this module is the translation between the two.
 */
import { DEFAULT_PAGE_SIZE, MAX_PAGE_SIZE } from "@/config/constants";
import type { Page } from "@/types/common";
import { makePage } from "@/types/common";

/** Number of pages a total spans; always at least 1 so the UI can render "1 of 1". */
export function pageCount(total: number, perPage: number): number {
  const size = clampPageSize(perPage);
  if (total <= 0) return 1;
  return Math.ceil(total / size);
}

/** Clamps a caller-supplied page size into the range the schemas allow. */
export function clampPageSize(perPage: number): number {
  if (!Number.isFinite(perPage) || perPage <= 0) return DEFAULT_PAGE_SIZE;
  return Math.min(Math.floor(perPage), MAX_PAGE_SIZE);
}

export function emptyPage<T>(): Page<T> {
  return makePage<T>([], null, 0);
}

/**
 * Trims an over-fetched row set to one page. Repositories query `limit + 1`
 * rows; if the extra row came back there is a next page, and its cursor is
 * the last kept row's cursor.
 */
export function sliceToPage<T>(
  items: readonly T[],
  limit: number,
  total: number,
  cursorOf: (item: T) => string,
): Page<T> {
  const size = clampPageSize(limit);
  const hasMore = items.length > size;
  const kept = hasMore ? items.slice(0, size) : items.slice();
  const last = kept[kept.length - 1];
  return makePage(kept, hasMore && last !== undefined ? cursorOf(last) : null, total);
}
